<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import AppIcon from '@trama/components/AppIcon.vue'
import NewConnectionModal from '@trama/components/connections/NewConnectionModal.vue'
import * as api from '@trama/services/api'
import { getApp } from '@trama/services/apps'
import { canonicalApp, createStepDraft, prepareStepDraft, schemaForStep, validateStepDraft } from '@trama/services/nodeSchemas'
import { toastError, toastInfo, toastSuccess } from '@trama/composables/useToast'
import MappedInput from './MappedInput.vue'
import JsonTree from './JsonTree.vue'
import VariableTree from './VariableTree.vue'
import FunctionPicker from './FunctionPicker.vue'
import CodeInput from './fields/CodeInput.vue'
import AgentChatPanel from './AgentChatPanel.vue'
import AgentToolFields from './AgentToolFields.vue'
import { agentAttachment, agentSlot } from './agentProjection.js'

const props = defineProps({ step: { type: Object, required: true }, index: { type: Number, default: 0 }, allSteps: { type: Array, default: () => [] }, fluxId: { type: String, required: true }, outputs: { type: Object, default: () => ({}) }, lastExecution: { type: Object, default: null }, testInput: { default: undefined }, edges: { type: Array, default: undefined }, beforeTest: { type: Function, default: undefined } })
const emit = defineEmits(['close', 'update', 'delete', 'tested', 'input-update'])
function enrichedDraft() {
  const attachment = agentAttachment(props.step.id, props.edges ?? [])
  const hasModel = props.edges?.some(edge => String(edge.source) === String(props.step.id) && agentSlot(edge) === 'model')
  return createStepDraft({ ...props.step, ...(props.edges !== undefined ? { agent_role: attachment?.role ?? null, agent_parent_id: attachment?.parentId ?? null } : {}), agent_has_model: props.edges !== undefined ? !!hasModel : props.step.agent_has_model })
}
const dialog = ref(null), draft = ref(enrichedDraft()), activeTab = ref('variables'), search = ref(''), advancedOpen = ref(false), newConnOpen = ref(false), testDataOpen = ref(false), testDataText = ref(''), testDataError = ref(''), localTestInput = ref(props.testInput), errors = ref({}), testing = ref(false), testedRecord = ref(null), testedExecution = ref(null), generalError = ref(''), editingTitle = ref(false), mobilePanel = ref('config'), webhookInfo = ref(null)
const fieldRefs = new Map()
const modelOptions = ref([]), modelsLoading = ref(false), modelsError = ref(''), agentChat = ref(null)
let modelsGeneration = 0
const listening = ref(false), rotating = ref(false), copyingLink = ref(''), pinnedCapture = ref(false), suppressOriginalOutput = ref(false), responseTab = ref('body'), expandedEditor = ref(false), headerRows = ref([]), headersExpression = ref(null)
let focusedField = null, previousFocus = null, alive = true, captureTimer = null, captureGeneration = 0
const clone = value => value === undefined ? undefined : JSON.parse(JSON.stringify(value))
const app = computed(() => canonicalApp(draft.value.app))
const schema = computed(() => schemaForStep(draft.value))
const isTrigger = computed(() => ['webhook', 'scheduler', 'activator'].includes(app.value) || props.index === 0 && !!getApp(draft.value.app).trigger)
const hasConnection = computed(() => !!schema.value.connection)
const requiresConnection = computed(() => hasConnection.value && !schema.value.connectionOptional)
const title = computed(() => draft.value.title || draft.value.label || schema.value.title || getApp(draft.value.app).title)
const visibleFields = computed(() => schema.value.fields.filter(field => !field.advanced || advancedOpen.value))
const hasAdvanced = computed(() => schema.value.fields.some(field => field.advanced))
const matchingConnections = computed(() => (api.db.connections || []).filter(connection => canonicalApp(connection.app) === app.value || app.value === 'ai_agent' && ['chatgpt', 'openai', 'anthropic', 'claude'].includes(connection.app)))
const selectedConnection = computed(() => matchingConnections.value.find(connection => connection.id === draft.value.connection_id))
const isAgent = computed(() => app.value === 'ai_agent' && draft.value.agent_role !== 'model')
const isAgentTool = computed(() => draft.value.agent_role === 'tools')
const modelListId = computed(() => 'agent-models-' + String(props.step.id))
async function loadModels() {
  const generation = ++modelsGeneration, id = draft.value.connection_id
  modelOptions.value = []; modelsError.value = ''; modelsLoading.value = false
  if (!id || draft.value.agent_role !== 'model') return
  modelsLoading.value = true
  try { const models = await api.listConnectionModels(id); if (alive && generation === modelsGeneration) modelOptions.value = Array.isArray(models) ? models : [] }
  catch (error) { if (alive && generation === modelsGeneration) modelsError.value = error.userMessage || error.message }
  finally { if (alive && generation === modelsGeneration) modelsLoading.value = false }
}
watch(() => [draft.value.connection_id, draft.value.agent_role], loadModels, { immediate: true })
const originalRecord = computed(() => props.lastExecution?.steps?.findLast(record => String(record.id) === String(props.step.id)) || (props.outputs[props.step.id] !== undefined ? { status: 'success', output: props.outputs[props.step.id] } : null))
const outputRecord = computed(() => testedRecord.value || (suppressOriginalOutput.value ? null : originalRecord.value))
const output = computed(() => outputRecord.value?.output)
const hasOutput = computed(() => outputRecord.value && Object.hasOwn(outputRecord.value, 'output') && output.value !== undefined)
const outputTree = computed(() => output.value !== null && typeof output.value === 'object' ? output.value : { result: output.value })
const outputStatus = computed(() => ({ success: 'Sucesso!', skipped: 'Ignorado', filtered: 'Filtrado', cancelled: 'Cancelado', interrupted: 'Interrompido', running: 'Executando…', queued: 'Aguardando…' })[outputRecord.value?.status] || 'Resultado')
const outputError = computed(() => outputRecord.value?.error || (outputRecord.value?.status === 'error' ? 'Não foi possível executar este módulo.' : ''))
const actualInput = computed(() => localTestInput.value ?? testedExecution.value?.input ?? props.lastExecution?.input ?? webhookInfo.value?.last_input)
const returnFormats = ['application/json', 'application/xml', 'multipart/form-data', 'text/html', 'text/xml', 'text/plain']
const responseStatuses = computed(() => [...new Set([200,201,202,204,205,206,207,208,226,300,301,302,303,304,305,307,308,400,401,402,403,404,405,406,407,408,409,410,411,412,413,414,415,416,417,418,421,422,423,424,425,426,428,429,431,451,500,501,502,503,504,505,506,507,508,510,511,Number(draft.value.config.status)||200])].sort((a,b)=>a-b))
const returnBodyText = computed(() => typeof draft.value.config.body === 'object' ? JSON.stringify(draft.value.config.body, null, 2) : String(draft.value.config.body ?? ''))
const returnLanguage = computed(() => ['application/json','multipart/form-data'].includes(draft.value.config.content_type) ? 'json' : draft.value.config.content_type === 'text/html' ? 'html' : draft.value.config.content_type?.includes('xml') ? 'xml' : 'text')
const upstreamIds = computed(() => {
  if (props.edges === undefined) return null
  const found = new Set()
  const visit = id => { for (const edge of props.edges) if (String(edge.target) === String(id) && !found.has(String(edge.source))) { found.add(String(edge.source)); visit(edge.source) } }
  visit(props.step.id)
  return found
})
const variableGroups = computed(() => {
  const input = actualInput.value
  const groups = [{ id: 'IN', displayId: 'IN', app: 'webhook', title: 'Webhook', output: input === undefined ? undefined : input?.BODY !== undefined ? input : { BODY: input } }]
  if (isAgentTool.value) groups.push({ id: 'AI', displayId: 'IA', app: 'ai_agent', title: 'Variáveis da IA', output: Object.fromEntries((Array.isArray(draft.value.ai_variables) ? draft.value.ai_variables : []).filter(item => item?.name).map(item => [item.name, item.description || 'Valor fornecido pelo agente'])) })
  for (const [index, step] of props.allSteps.entries()) {
    if (String(step.id) === String(props.step.id) || ['webhook', 'scheduler', 'activator'].includes(canonicalApp(step.app))) continue
    if (upstreamIds.value ? !upstreamIds.value.has(String(step.id)) : index >= props.index) continue
    const record = (testedExecution.value?.steps || props.lastExecution?.steps || []).findLast(item => String(item.id) === String(step.id))
    const value = props.outputs[step.id] ?? record?.output ?? step.last_output
    groups.push({ id: String(step.id), displayId: step.variable_id || step.id, app: step.app, title: step.title || getApp(step.app).title, output: typeof value === 'object' || value === undefined || value === null ? value : { result: value } })
  }
  return groups
})
watch(() => props.step.id, () => { stopListening(); draft.value = enrichedDraft(); errors.value = {}; generalError.value = ''; testedRecord.value = null; testedExecution.value = null; pinnedCapture.value = false; suppressOriginalOutput.value = false; fieldRefs.clear(); focusedField = null; initializeHeaders(); loadWebhook() })
watch(() => props.testInput, input => { localTestInput.value = clone(input) })
function fieldValue(field) { const value = draft.value.config[field.key]; return field.type === 'json' && typeof value === 'object' ? JSON.stringify(value, null, 2) : value ?? '' }
function setField(field, value) { draft.value.config[field.key] = value; delete errors.value[field.key] }
function rememberField(key) { focusedField = key }
function registerField(key, element) { if (element) fieldRefs.set(key, element); else fieldRefs.delete(key) }
async function insertVariable(reference) {
  const target = fieldRefs.get(focusedField)
  if (target?.insert) target.insert(reference)
  else { await navigator.clipboard.writeText(reference); toastInfo({ text: 'Variável copiada. Clique em um campo para inserir diretamente.' }) }
}
async function loadWebhook() {
  webhookInfo.value = null
  if (!api.db.capabilities?.external_webhooks || canonicalApp(props.step.app) !== 'webhook' || typeof api.getWebhookInfo !== 'function') return
  try { const info = await api.getWebhookInfo(props.fluxId); if (alive) webhookInfo.value = info } catch (error) { generalError.value = error.userMessage || error.message }
}
async function copyLink(mode) {
  const value = mode === 'test' ? webhookInfo.value?.test_url : webhookInfo.value?.sync_url
  if (!value) return
  try { await navigator.clipboard.writeText(value); copyingLink.value = mode; setTimeout(() => { if (alive) copyingLink.value = '' }, 1500) } catch { toastError({ text: 'Não foi possível copiar o link.' }) }
}
async function rotateWebhook() {
  rotating.value = true;generalError.value = '';stopListening()
  try { const info = await api.rotateWebhookToken(props.fluxId); if (alive) { webhookInfo.value = info; toastSuccess({ text: 'Novos links gerados. Os links anteriores foram revogados.' }) } }
  catch(error) { if (alive) generalError.value = error.userMessage || error.message }
  finally { if (alive) rotating.value = false }
}
function stopListening() { captureGeneration++;clearTimeout(captureTimer);captureTimer = null;listening.value = false }
function pinInput(value, receivedAt, persist = true) {
  const payload = clone(value ?? {})
  localTestInput.value = payload;draft.value.config.sample = clone(payload);draft.value.config.sample_pinned = true;pinnedCapture.value = true;suppressOriginalOutput.value = false
  testedRecord.value = { status:'success', captured_at:receivedAt, output:{ BODY:payload } }
  if (persist) emit('input-update', clone(payload))
}
async function listenWebhook() {
  if (listening.value) { stopListening();return }
  generalError.value = ''
  if (!api.db.capabilities?.external_webhooks || typeof api.getWebhookCapture !== 'function') { generalError.value = 'O serviço de captura ainda não está disponível.';return }
  try {
    const initial = await api.getWebhookCapture(props.fluxId)
    if (!alive) return
    const baseline = initial.last_received_at, generation = ++captureGeneration, started = Date.now()
    listening.value = true
    const poll = async () => {
      if (!alive || generation !== captureGeneration) return
      try {
        const capture = await api.getWebhookCapture(props.fluxId)
        if (!alive || generation !== captureGeneration) return
        if (capture.last_received_at && capture.last_received_at !== baseline) {
          webhookInfo.value = { ...webhookInfo.value, ...capture };pinInput(capture.last_input,capture.last_received_at);stopListening();mobilePanel.value = 'output';toastSuccess({ text:'Chamada recebida. A entrada está fixada para teste.' });return
        }
        if (Date.now()-started >= 120000) { stopListening();toastInfo({ text:'A escuta foi encerrada. Clique em Testar Webhook para aguardar outra chamada.' });return }
        captureTimer = setTimeout(poll,1500)
      } catch(error) { if (alive && generation === captureGeneration) { stopListening();generalError.value = error.userMessage || error.message } }
    }
    captureTimer = setTimeout(poll,700)
  } catch(error) { if (alive) generalError.value = error.userMessage || error.message }
}
function clearPinnedInput() { stopListening();pinnedCapture.value = false;suppressOriginalOutput.value = true;testedRecord.value = null;testedExecution.value = null;localTestInput.value = {};delete draft.value.config.sample;draft.value.config.sample_pinned = false;emit('input-update',{}); }
function initializeHeaders() {
  let headers = draft.value.config.headers ?? {}
  headersExpression.value = typeof headers === 'string' && /^\s*\{\{[\s\S]+\}\}\s*$/.test(headers) ? headers : null
  if (typeof headers === 'string') { try { headers = JSON.parse(headers) } catch { headers = {} } }
  if (!headers || typeof headers !== 'object' || Array.isArray(headers)) headers = {}
  headerRows.value = Object.entries(headers).map(([key,value],index)=>({ id:Date.now()+index,key,value:String(value) }))
  if (!headerRows.value.length) headerRows.value = [{ id:Date.now(),key:'Content-Type',value:draft.value.config.content_type || 'application/json' }]
}
function syncHeaders() {
  draft.value.config.headers = headersExpression.value ?? Object.fromEntries(headerRows.value.filter(row=>row.key.trim()).map(row=>[row.key.trim(),row.value]))
  if (headersExpression.value === null) {
    const contentType = headerRows.value.findLast(row=>row.key.trim().toLowerCase()==='content-type')?.value?.split(';')[0].trim().toLowerCase()
    if (returnFormats.includes(contentType)) { draft.value.config.content_type = contentType;delete errors.value.body }
  }
  delete errors.value.headers
}
function selectResponseTab(tab, focus = false) { responseTab.value = tab;if (focus) nextTick(()=>dialog.value?.querySelector(`[data-response-tab="${tab}"]`)?.focus()) }
function useHeaderPairs() { headersExpression.value = null;syncHeaders() }
function addHeader() { headerRows.value.push({ id:Date.now()+Math.random(),key:'',value:'' }) }
function removeHeader(index) { headerRows.value.splice(index,1);syncHeaders() }
function changeReturnFormat(value) {
  draft.value.config.content_type = value
  for(const row of headerRows.value) if(row.key.toLowerCase()==='content-type') row.value=value
  syncHeaders();delete errors.value.body
}
function save() {
  if (app.value === 'return') syncHeaders()
  errors.value = validateStepDraft(draft.value)
  if (requiresConnection.value && !draft.value.connection_id) errors.value.connection_id = 'Selecione uma conexão.'
  if (Object.keys(errors.value).length) { generalError.value = 'Revise os campos destacados antes de salvar.'; return }
  generalError.value = ''
  emit('update', prepareStepDraft(draft.value))
  emit('close')
}
function acceptAgentTest(result) {
  testedExecution.value = result
  testedRecord.value = result.steps?.findLast(record => String(record.id) === String(props.step.id)) || { status: result.status, output: result.output, error: result.error }
  emit('tested', result)
}
async function prepareChat(message) {
  const stepId = String(props.step.id)
  const candidate = { ...draft.value, config: { ...draft.value.config, user_prompt: message } }
  errors.value = validateStepDraft(candidate)
  if (requiresConnection.value && !candidate.connection_id) errors.value.connection_id = 'Selecione uma conexão.'
  if (Object.keys(errors.value).length) { generalError.value = 'Revise os campos destacados antes de conversar com o agente.'; throw new Error(generalError.value) }
  generalError.value = ''
  if (props.beforeTest && await props.beforeTest() === false) throw new Error('Não foi possível salvar o fluxo antes do teste. Tente novamente.')
  if (!alive || stepId !== String(props.step.id)) throw new Error('O módulo foi fechado antes do teste.')
  return prepareStepDraft(candidate)
}
async function test() {
  if (isAgent.value) { mobilePanel.value = 'output'; nextTick(() => agentChat.value?.focus()); return }
  if (app.value === 'webhook') return listenWebhook()
  if (app.value === 'return') syncHeaders()
  errors.value = validateStepDraft(draft.value)
  if (requiresConnection.value && !draft.value.connection_id) errors.value.connection_id = 'Selecione uma conexão.'
  if (Object.keys(errors.value).length) { generalError.value = 'Revise os campos destacados antes de testar.'; return }
  generalError.value = ''
  testing.value = true
  try {
    const stepId = String(props.step.id)
    if (props.beforeTest && await props.beforeTest() === false) throw new Error('Não foi possível salvar o fluxo antes do teste. Tente novamente.')
    if (!alive || stepId !== String(props.step.id)) return
    if (typeof api.testFluxStep !== 'function') throw new Error('O serviço de teste ainda não está disponível. Verifique se o servidor está em execução.')
    const context = Object.fromEntries(variableGroups.value.filter(group => group.output !== undefined).map(group => [group.id, clone(group.output)]))
    const result = await api.testFluxStep(props.fluxId, props.step.id, { step: prepareStepDraft(draft.value), input: actualInput.value ?? {}, context })
    if (!alive) return
    testedExecution.value = result
    testedRecord.value = result.steps?.findLast(record => String(record.id) === String(props.step.id)) || { status: result.status, output: result.output, error: result.error }
    emit('tested', result)
    if (testedRecord.value.status === 'success') toastSuccess({ text: 'Teste concluído.' })
    mobilePanel.value = 'output'
  } catch (error) { if (alive) testedRecord.value = { status: 'error', error: error.userMessage || error.message, output: error.output } }
  finally { if (alive) testing.value = false }
}
function editInput() { testDataText.value = JSON.stringify(actualInput.value ?? {}, null, 2); testDataError.value = ''; testDataOpen.value = true }
function applyInput() { try { localTestInput.value = JSON.parse(testDataText.value); draft.value.config.sample = clone(localTestInput.value); if (app.value === 'webhook') pinInput(localTestInput.value,new Date().toISOString());else emit('input-update', clone(localTestInput.value));testDataOpen.value = false } catch { testDataError.value = 'Informe um JSON válido.' } }
function connectionCreated(connection) { draft.value.connection_id = connection.id; delete errors.value.connection_id }
function close() { emit('close') }
function keydown(event) {
  if (newConnOpen.value || testDataOpen.value || expandedEditor.value) return
  if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close() }
  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 's') { event.preventDefault();event.stopPropagation();save() }
  if (event.key === 'Tab') {
    const elements = [...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[contenteditable="true"],a[href]')].filter(el => el.getClientRects().length && el.tabIndex !== -1)
    const first = elements[0], last = elements.at(-1)
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
  }
}
onMounted(async () => { previousFocus = document.activeElement; document.addEventListener('keydown', keydown);initializeHeaders();await loadWebhook();if(app.value === 'webhook' && draft.value.config.sample_pinned === true)pinInput(draft.value.config.sample,webhookInfo.value?.last_received_at,false);else if(webhookInfo.value?.last_received_at && draft.value.config.sample_pinned !== false && JSON.stringify(props.testInput)===JSON.stringify(webhookInfo.value.last_input))pinInput(webhookInfo.value.last_input,webhookInfo.value.last_received_at,false);await nextTick(); dialog.value?.querySelector('.node-config__close')?.focus({ preventScroll: true }) })
onBeforeUnmount(() => { alive = false;stopListening();document.removeEventListener('keydown', keydown); previousFocus?.focus?.({ preventScroll: true }) })
</script>

<template>
  <div class="node-dialog-backdrop" @mousedown.self="close">
    <div ref="dialog" class="node-dialog" :class="{ 'node-dialog--webhook': app === 'webhook' }" role="dialog" aria-modal="true" :aria-label="`Configurar ${title}`" @mousedown.stop>
      <header class="node-dialog__identity"><span class="node-dialog__app"><AppIcon :app="draft.app" :size="30" :rounded="8" /></span><div><p>TRAMA <span>/</span> {{ isTrigger ? 'GATILHO' : 'MÓDULO' }} <span>/</span> {{ step.id }}</p><h2>{{ title }}</h2></div><button type="button" class="node-config__close" aria-label="Fechar configuração do módulo" @click="close"><v-icon icon="mdi-close" size="21" /></button></header>
      <nav class="node-dialog__mobile-tabs" aria-label="Painéis do módulo"><button v-if="app !== 'webhook'" :aria-pressed="mobilePanel === 'input'" :class="{ selected: mobilePanel === 'input' }" @click="mobilePanel = 'input'">Entrada</button><button :aria-pressed="mobilePanel === 'config'" :class="{ selected: mobilePanel === 'config' }" @click="mobilePanel = 'config'">Configuração</button><button :aria-pressed="mobilePanel === 'output'" :class="{ selected: mobilePanel === 'output' }" @click="mobilePanel = 'output'">Saída</button></nav>
      <aside v-if="app !== 'webhook'" class="node-side-panel node-input" :class="{ 'mobile-visible': mobilePanel === 'input' }">
        <header class="node-panel-title"><span class="node-panel-number">01</span><div><strong>Entrada</strong><small>Dados e variáveis</small></div></header>
        <div class="node-input-tabs" role="tablist" aria-label="Dados de entrada"><button :id="`input-tab-variables-${step.id}`" role="tab" :aria-controls="`input-panel-variables-${step.id}`" :tabindex="activeTab === 'variables' ? 0 : -1" :aria-selected="activeTab === 'variables'" :class="{ selected: activeTab === 'variables' }" @click="activeTab = 'variables'"><v-icon icon="mdi-code-tags" size="15" />Variáveis</button><button :id="`input-tab-functions-${step.id}`" role="tab" :aria-controls="`input-panel-functions-${step.id}`" :tabindex="activeTab === 'functions' ? 0 : -1" :aria-selected="activeTab === 'functions'" :class="{ selected: activeTab === 'functions' }" @click="activeTab = 'functions'"><v-icon icon="mdi-cog-outline" size="14" />Funções</button></div>
        <div class="node-input__search"><v-icon icon="mdi-magnify" size="16" /><input v-model="search" :aria-label="activeTab === 'variables' ? 'Buscar variáveis' : 'Buscar funções'" /></div>
        <div :id="`input-panel-${activeTab}-${step.id}`" class="node-input__tree" role="tabpanel" :aria-labelledby="`input-tab-${activeTab}-${step.id}`"><VariableTree v-if="activeTab === 'variables'" :groups="variableGroups" :search="search" @select="insertVariable" /><FunctionPicker v-else :search="search" @select="insertVariable" /></div>
        <button class="node-input__edit-data" @click="editInput"><v-icon icon="mdi-code-json" size="14" />Dados de teste</button>
      </aside>

      <section class="node-config" :class="{ 'mobile-visible': mobilePanel === 'config' }">
        <header class="node-config__header"><span class="node-panel-number">{{ app === 'webhook' ? '01' : '02' }}</span><div class="node-config__heading"><small>Configuração</small><input v-if="editingTitle" v-model="draft.title" class="node-config__title-input" aria-label="Nome do módulo" autofocus @blur="editingTitle = false" @keydown.enter="editingTitle = false" /><button v-else class="node-config__title" aria-label="Renomear módulo" @click="draft.title = title; editingTitle = true">{{ title }}<v-icon icon="mdi-pencil-outline" size="15" /></button></div></header>
        <div class="node-config__body">
          <div v-if="hasConnection" class="node-connection-wrap"><div class="node-connection" :class="{ invalid: errors.connection_id }"><span class="node-connection__icon"><AppIcon :app="selectedConnection?.app || draft.app" :size="20" :rounded="2" /></span><select v-model="draft.connection_id" aria-label="Conexão" @change="delete errors.connection_id"><option :value="undefined" :disabled="requiresConnection">{{ requiresConnection ? 'Selecione uma conexão' : 'Sem autenticação' }}</option><option v-for="connection in matchingConnections" :key="connection.id" :value="connection.id">{{ connection.name }}</option></select><v-icon icon="mdi-chevron-down" size="16" class="node-connection__chevron" /><button class="node-connection__add" aria-label="Adicionar conexão" @click="newConnOpen = true"><v-icon icon="mdi-plus" size="22" /></button></div><p v-if="errors.connection_id" class="node-field-error">{{ errors.connection_id }}</p></div>
          <p class="node-config__description">{{ schema.description }}</p>
          <div class="node-config__fields">
            <AgentToolFields v-if="isAgentTool" v-model="draft" :errors="errors" />
            <p v-if="['scheduler', 'code'].includes(app) || app === 'webhook' && !api.db.capabilities?.external_webhooks" class="node-error-banner">{{ app === 'code' ? 'O código pode ser guardado no fluxo, mas a execução de JavaScript ainda não está disponível.' : app === 'scheduler' ? 'Agendamentos ainda não estão disponíveis. Use Rodar para executar manualmente.' : 'O serviço de webhooks ainda não foi configurado. Você pode usar Rodar com uma entrada de teste.' }}</p><template v-if="app === 'webhook' && api.db.capabilities?.external_webhooks">
              <div class="node-field"><div class="webhook-label-row"><label><span class="webhook-environment">Produção</span>Link de ativação</label><button class="webhook-rotate" :disabled="rotating || !webhookInfo" @click="rotateWebhook"><v-icon :icon="rotating ? 'mdi-loading mdi-spin' : 'mdi-refresh'" size="14" />Gerar novo link</button></div><div class="node-webhook-url"><input :value="webhookInfo?.sync_url || 'Carregando link…'" readonly aria-label="Link de ativação do Webhook" /><button :disabled="!webhookInfo?.sync_url" :aria-label="copyingLink === 'sync' ? 'Link de produção copiado' : 'Copiar link de produção'" @click="copyLink('sync')"><v-icon :icon="copyingLink === 'sync' ? 'mdi-check' : 'mdi-content-copy'" size="17" /></button></div><p class="webhook-link-help">Executa a versão publicada quando o fluxo está ativo. A chamada espera a resposta por até 30 segundos.</p></div>
              <div class="node-field"><label><span class="webhook-environment webhook-environment--test">Teste</span>Link de teste</label><div class="node-webhook-url"><input :value="webhookInfo?.test_url || 'Carregando link…'" readonly aria-label="Link de teste do Webhook" /><button :disabled="!webhookInfo?.test_url" :aria-label="copyingLink === 'test' ? 'Link de teste copiado' : 'Copiar link de teste'" @click="copyLink('test')"><v-icon :icon="copyingLink === 'test' ? 'mdi-check' : 'mdi-content-copy'" size="17" /></button></div><p class="webhook-link-help">Captura a entrada e mostra os dados na saída, sem executar o fluxo.</p></div>
              <p class="webhook-listening-note" :class="{ 'is-listening': listening }" role="status"><v-icon :icon="listening ? 'mdi-radar' : 'mdi-lightning-bolt-outline'" size="20" /><span>{{ listening ? 'Aguardando uma chamada no link de teste. Envie os dados para fixar a resposta na saída.' : 'Clique em Testar Webhook para abrir a escuta. A próxima chamada ao link de teste aparecerá na saída.' }}</span></p>
              <button class="node-test-primary" :disabled="rotating || !webhookInfo?.test_url" @click="listenWebhook"><v-icon :icon="listening ? 'mdi-stop' : 'mdi-play-outline'" size="17" />{{ listening ? 'Cancelar escuta' : 'Testar Webhook' }}</button>
              <div class="node-webhook-recent"><h4>Execuções recentes</h4><div class="node-webhook-recent__head"><span>Origem</span><span>Executado em</span><span>Resultado</span></div><p v-if="!webhookInfo?.last_received_at">Nenhum teste realizado ainda</p><div v-else class="node-webhook-recent__item"><span>Webhook</span><span>{{ new Date(webhookInfo.last_received_at).toLocaleString('pt-BR') }}</span><button @click="editInput">Ver entrada</button></div></div>
            </template>
            <template v-if="app === 'return'">
              <div class="return-format-row"><div class="node-field"><label for="return-format">Formato</label><select id="return-format" :value="draft.config.content_type" class="node-select" aria-label="Formato de resposta" @change="changeReturnFormat($event.target.value)"><option v-for="format in returnFormats" :key="format" :value="format">{{ format }}</option></select></div><div class="node-field"><label for="return-status">Código de resposta</label><select id="return-status" v-model="draft.config.status" class="node-select" aria-label="Código de resposta"><option v-for="code in responseStatuses" :key="code" :value="code">{{ code }}</option></select><p v-if="errors.status" class="node-field-error">{{ errors.status }}</p></div></div>
              <div class="return-tabs" role="tablist" aria-label="Resposta do Webhook" @keydown.right.prevent="selectResponseTab(responseTab === 'body' ? 'headers' : 'body',true)" @keydown.left.prevent="selectResponseTab(responseTab === 'body' ? 'headers' : 'body',true)" @keydown.home.prevent="selectResponseTab('body',true)" @keydown.end.prevent="selectResponseTab('headers',true)"><button :id="`return-tab-body-${step.id}`" role="tab" aria-label="Body" data-response-tab="body" :aria-controls="`return-panel-body-${step.id}`" :aria-selected="responseTab === 'body'" :tabindex="responseTab === 'body' ? 0 : -1" :class="{ selected: responseTab === 'body' }" @click="selectResponseTab('body')">Body</button><button :id="`return-tab-headers-${step.id}`" role="tab" aria-label="Headers" data-response-tab="headers" :aria-controls="`return-panel-headers-${step.id}`" :aria-selected="responseTab === 'headers'" :tabindex="responseTab === 'headers' ? 0 : -1" :class="{ selected: responseTab === 'headers' }" @click="selectResponseTab('headers')">Headers<span aria-hidden="true">{{ headerRows.filter(row=>row.key.trim()).length }}</span></button></div>
              <div v-if="responseTab === 'body'" :id="`return-panel-body-${step.id}`" role="tabpanel" :aria-labelledby="`return-tab-body-${step.id}`" class="return-body"><CodeInput :ref="el => registerField('body', el)" :model-value="returnBodyText" :language="returnLanguage" :rows="15" label="Body da resposta" :invalid="!!errors.body" @focus="rememberField('body')" @update:model-value="setField({key:'body'},$event)" /><p v-if="errors.body" class="node-field-error">{{ errors.body }}</p><button class="return-expand" @click="expandedEditor = true"><v-icon icon="mdi-arrow-expand" size="16" />Expandir editor</button></div>
              <div v-else :id="`return-panel-headers-${step.id}`" role="tabpanel" :aria-labelledby="`return-tab-headers-${step.id}`" class="return-headers"><template v-if="headersExpression !== null"><label class="return-expression-label">Objeto de headers mapeado</label><MappedInput v-model="headersExpression" label="Objeto de headers mapeado" @update:model-value="syncHeaders" /><button class="return-add-header" @click="useHeaderPairs">Editar como pares de nome e valor</button></template><template v-else><div v-for="(row,index) in headerRows" :key="row.id" class="return-header-row"><input v-model="row.key" :aria-label="`Nome do header ${index+1}`" placeholder="Header" spellcheck="false" @input="syncHeaders" /><MappedInput v-model="row.value" :label="`Valor do header ${index+1}`" placeholder="Valor" @focus="rememberField('headers')" @update:model-value="syncHeaders" /><button :aria-label="`Remover header ${index+1}`" @click="removeHeader(index)"><v-icon icon="mdi-trash-can-outline" size="17" /></button></div><button class="return-add-header" @click="addHeader"><v-icon icon="mdi-plus" size="17" />Adicionar header</button></template><p v-if="errors.headers" class="node-field-error">{{ errors.headers }}</p></div>
            </template>
            <div v-for="field in app === 'return' ? [] : visibleFields" :key="`${draft.app}-${field.key}`" class="node-field">
              <div class="node-field__label-row"><label :for="`node-field-${field.key}`">{{ field.label }}<span v-if="field.required" class="node-required">*</span><span v-if="field.hint || field.required" class="node-label-help" :title="field.hint || 'Campo obrigatório'">ⓘ</span></label><label v-if="field.custom" class="node-custom-toggle">Customizado<input v-model="draft.config[`${field.key}_custom`]" type="checkbox" role="switch" /></label></div>
              <div v-if="draft.agent_role === 'model' && field.key === 'model'" class="agent-model-picker"><div><input :id="`node-field-${field.key}`" v-model="draft.config.model" :list="modelListId" class="node-number" :class="{ invalid: errors.model }" aria-label="Modelo" placeholder="Selecione ou informe o modelo" spellcheck="false" @input="delete errors.model" /><button type="button" :disabled="modelsLoading || !draft.connection_id" aria-label="Atualizar modelos da conexão" @click="loadModels"><v-icon :icon="modelsLoading ? 'mdi-loading mdi-spin' : 'mdi-refresh'" size="18" /></button></div><datalist :id="modelListId"><option v-for="model in modelOptions" :key="model.value" :value="model.value">{{ model.label }}</option></datalist><p role="status">{{ modelsLoading ? 'Consultando modelos disponíveis…' : modelsError ? 'Não foi possível listar os modelos. Informe um identificador disponível na conexão.' : modelOptions.length ? 'Escolha um modelo da conexão ou informe outro identificador.' : 'Selecione uma conexão e informe o identificador do modelo.' }}</p></div>
              <CodeInput v-else-if="['json', 'code'].includes(field.type)" :ref="el => registerField(field.key, el)" :model-value="fieldValue(field)" :language="field.type === 'json' ? 'json' : field.language || 'javascript'" :rows="field.rows || 10" :label="field.label" :invalid="!!errors[field.key]" @focus="rememberField(field.key)" @update:model-value="setField(field, $event)" />
              <select v-else-if="field.type === 'select' && !draft.config[`${field.key}_custom`]" :id="`node-field-${field.key}`" v-model="draft.config[field.key]" class="node-select" :class="{ invalid: errors[field.key] }" :aria-label="field.label" @change="delete errors[field.key]"><option v-for="option in field.options || []" :key="String(typeof option === 'object' ? option.value : option)" :value="typeof option === 'object' ? option.value : option">{{ typeof option === 'object' ? option.title || option.label : option }}</option></select>
              <label v-else-if="field.type === 'boolean'" class="node-boolean"><input :id="`node-field-${field.key}`" v-model="draft.config[field.key]" type="checkbox" role="switch" />{{ draft.config[field.key] ? 'Sim' : 'Não' }}</label>
              <input v-else-if="field.type === 'number'" :id="`node-field-${field.key}`" v-model="draft.config[field.key]" type="number" class="node-number" :class="{ invalid: errors[field.key] }" :min="field.min" :max="field.max" :step="field.step || 1" :aria-label="field.label" @input="delete errors[field.key]" />
              <MappedInput v-else :ref="el => registerField(field.key, el)" :model-value="fieldValue(field)" :multiline="field.type === 'textarea'" :rows="field.rows || (field.type === 'textarea' ? 3 : 1)" :label="field.label" :placeholder="field.placeholder" :invalid="!!errors[field.key]" @focus="rememberField(field.key)" @update:model-value="setField(field, $event)" />
              <p v-if="errors[field.key]" class="node-field-error">{{ errors[field.key] }}</p>
            </div>
            <button v-if="hasAdvanced" class="node-advanced" :aria-expanded="advancedOpen" @click="advancedOpen = !advancedOpen"><v-icon :icon="advancedOpen ? 'mdi-chevron-up' : 'mdi-chevron-down'" size="14" />Opções avançadas</button><p v-if="generalError" class="node-error-banner" role="alert">{{ generalError }}</p>
          </div>
          <div v-if="!isTrigger && app !== 'filter'" class="node-fatal"><label for="node-is-fatal">Erro interrompe o fluxo</label><input id="node-is-fatal" v-model="draft.is_fatal" type="checkbox" role="switch" aria-label="Erro interrompe o fluxo" /></div>
        </div>
        <footer class="node-config__footer"><span class="node-save-hint">Ctrl / ⌘ + S</span><button class="node-save" @click="save"><v-icon icon="mdi-check" size="18" />Salvar módulo</button></footer>
      </section>

      <aside class="node-side-panel node-output" :class="{ 'mobile-visible': mobilePanel === 'output' }"><header class="node-panel-title"><span class="node-panel-number">{{ app === 'webhook' ? '02' : '03' }}</span><div><strong>{{ isAgent ? 'Conversa' : 'Saída' }}</strong><small>{{ isAgent ? 'Chat de teste' : 'Resultado do módulo' }}</small></div></header><div class="node-output__body">
        <AgentChatPanel v-if="isAgent" ref="agentChat" :key="String(step.id)" :flux-id="fluxId" :step-id="step.id" :input="actualInput" :prepare="prepareChat" @tested="acceptAgentTest" />
        <div v-else-if="['model','memory'].includes(draft.agent_role)" class="node-output__empty"><span class="node-empty-app"><AppIcon :app="draft.app" :size="48" :rounded="12" /></span><h3>{{ draft.agent_role === 'model' ? 'Modelo do agente' : 'Memória do agente' }}</h3><p>{{ draft.agent_role === 'model' ? 'Esta conexão e este modelo serão usados pelo agente. Salve a configuração e abra o chat do agente para testar.' : 'As mensagens da mesma sessão compartilham este histórico. Salve a configuração e abra o chat do agente para testar a conversa.' }}</p></div>
        <template v-else><div v-if="pinnedCapture && hasOutput" class="node-pinned-label"><v-icon icon="mdi-pin" size="16" />Resposta fixada</div>
        <div v-if="hasOutput || outputError || testing" class="node-output__status-row"><span class="node-status" :class="{ 'node-status--error': outputError, 'node-status--loading': testing }"><v-icon :icon="testing ? 'mdi-loading mdi-spin' : outputError ? 'mdi-alert-circle-outline' : 'mdi-check'" size="15" />{{ testing ? 'Executando…' : outputError ? 'Erro' : pinnedCapture ? 'Entrada capturada' : outputStatus }}</span><button class="node-retest" :disabled="testing || listening" @click="test"><v-icon icon="mdi-refresh" size="16" />{{ app === 'webhook' ? 'Nova captura' : 'Testar novamente' }}</button></div>
        <p v-if="outputError" class="node-output__error" role="alert">{{ typeof outputError === 'object' ? outputError.message || JSON.stringify(outputError) : outputError }}</p><JsonTree v-if="hasOutput" :value="outputTree" />
