    <v-dialog v-model="expandedEditor" width="min(1100px, 94vw)"><section class="node-test-data return-expanded"><header><h3>Body da resposta</h3><button aria-label="Fechar editor expandido" @click="expandedEditor = false"><v-icon icon="mdi-close" size="20" /></button></header><CodeInput v-if="expandedEditor" :model-value="returnBodyText" :language="returnLanguage" :rows="24" label="Body da resposta em tela expandida" :invalid="!!errors.body" @update:model-value="setField({key:'body'},$event)" /><footer><button class="node-save" @click="expandedEditor = false">Concluir</button></footer></section></v-dialog>
  </div>
</template>

